jq("j-f-collectors", "Streams: Collecting to List, Set and Map", "MEDIUM", T, "Read `n` words. Collect them into a `List` (print its size), a `Set` (print its size) and a `Map` from each word to its length (use `toMap` with a merge function so repeated words are fine; print the entries sorted by key as `word=length` on one line).", "First line `n`, then `n` words.", "Three lines.", "1 <= n <= 50",
   'List<String> list = Arrays.stream(w).collect(Collectors.toList());\nSet<String> set = Arrays.stream(w).collect(Collectors.toSet());\nMap<String, Integer> map = Arrays.stream(w).collect(Collectors.toMap(s -> s, String::length, (x, y) -> x, TreeMap::new));\nSystem.out.println("List: " + list.size());\nSystem.out.println("Set: " + set.size());\nSystem.out.println(map.entrySet().stream().map(e -> e.getKey() + "=" + e.getValue()).collect(Collectors.joining(" ")));', ["4\nred green red blue", "1\nsolo", "3\na a a", "3\nbb a ccc", "2\nx yy"], WORDS, imports=ST)
jq("j-f-grouping-by", "Streams: groupingBy a Category", "MEDIUM", T, "Read `n` words and group them by their **first letter** with `Collectors.groupingBy` into a `TreeMap`. Print one line per letter as `<letter>: <words in the order read, separated by commas>`.", "First line `n`, then `n` words.", "One line per letter.", "1 <= n <= 50",
   'Map<Character, List<String>> g = Arrays.stream(w).collect(Collectors.groupingBy(s -> s.charAt(0), TreeMap::new, Collectors.toList()));\nfor (Map.Entry<Character, List<String>> e : g.entrySet()) System.out.println(e.getKey() + ": " + String.join(",", e.getValue()));', ["5\napple banana avocado cherry blueberry", "1\nsolo", "3\nxa xb xc", "4\nd c b a", "2\nzebra zoo"], WORDS, imports=ST)
jq("j-f-partitioning-by", "Streams: partitioningBy", "MEDIUM", T, "Read `n` integers and split them with `Collectors.partitioningBy` into the even and the odd numbers. Print `Even: <numbers>` and `Odd: <numbers>` (the original order; `none` if empty).", "First line `n`, then `n` integers.", "Two lines.", "1 <= n <= 100",
   'Map<Boolean, List<Integer>> p = Arrays.stream(a).boxed().collect(Collectors.partitioningBy(x -> x % 2 == 0));\nfor (boolean even : new boolean[] {true, false}) {\n    String s = p.get(even).stream().map(String::valueOf).collect(Collectors.joining(" "));\n    System.out.println((even ? "Even: " : "Odd: ") + (s.isEmpty() ? "none" : s));\n}', [arr([1, 2, 3, 4, 5]), arr([2, 4]), arr([7]), arr([-3, -2, 0]), arr([10, 11, 12, 13])], [("arr", "n a")], imports=ST)
