jq("j-f-dynamic-proxy", "A Dynamic Proxy", "HARD", T, "Create a `java.lang.reflect.Proxy` for the interface `Calculator` (`int add(int, int)`). The proxy's handler prints `Calling <method name>` and then calls the real object. Read `a b`; print the `Calling add` line (printed by the handler) and then `Result: <a + b>`.", "One line: `a b`.", "Two lines.", "|values| <= 1000",
   'Calculator real = (x, y) -> x + y;\nCalculator proxy = (Calculator) Proxy.newProxyInstance(Calculator.class.getClassLoader(), new Class<?>[] {Calculator.class}, (p, method, callArgs) -> {\n    System.out.println("Calling " + method.getName());\n    return method.invoke(real, callArgs);\n});\nSystem.out.println("Result: " + proxy.add(a, b));', ["3 4", "-2 5", "0 0", "100 200", "7 -7"], [("int", "a b")], imports="java.lang.reflect.*",
   classes='interface Calculator {\n    int add(int a, int b);\n}')
jq("j-f-logging-callbacks", "A Logging Framework with Callbacks", "HARD", T, "Write `class Logger` that holds a list of `Consumer<String>` handlers and a minimum level (`INFO` < `WARN` < `ERROR`). `log(level, text)` sends `[<LEVEL>] <text>` to every handler when the level is at least the minimum. Read the minimum level, then `n` lines `LEVEL text` (text is one word); register a handler that prints the message and another that counts messages. Print the passing messages as they arrive, then `Handled: <count>`.", "Line 1 the minimum level; line 2 `n`; then `n` lines `LEVEL text`.", "The messages then a count.", "1 <= n <= 50",
   'Logger logger = new Logger(Level.valueOf(in.next()));\nint[] count = {0};\nlogger.addHandler(System.out::println);\nlogger.addHandler(msg -> count[0]++);\nint n = in.nextInt();\nfor (int i = 0; i < n; i++) logger.log(Level.valueOf(in.next()), in.next());\nSystem.out.println("Handled: " + count[0]);', ["WARN\n3\nINFO start\nWARN careful\nERROR boom", "INFO\n2\nINFO a\nINFO b", "ERROR\n3\nINFO x\nWARN y\nERROR z", "WARN\n1\nINFO quiet", "INFO\n1\nERROR bad"], [], imports="java.util.function.Consumer", scanner=True,
   classes='enum Level {\n    INFO, WARN, ERROR\n}\n\nclass Logger {\n    private final Level min;\n    private final List<Consumer<String>> handlers = new ArrayList<>();\n    Logger(Level min) {\n        this.min = min;\n    }\n    void addHandler(Consumer<String> h) {\n        handlers.add(h);\n    }\n    void log(Level level, String text) {\n        if (level.compareTo(min) < 0) return;\n        for (Consumer<String> h : handlers) h.accept("[" + level + "] " + text);\n    }\n}')
jq("j-f-json-parser", "Parsing JSON-like Text", "HARD", T, "Parse text like `{name:asha,age:20,city:pune}` into a map: split on commas and colons. A value made only of digits becomes an `Integer`, anything else stays a `String` (decide with a small function `Function<String, Object>`). Print the entries sorted by key as `key=value (<Integer or String>)`.", "One line like `{key:value,key:value}` without spaces.", "One line per key.", "At most 20 pairs",
   'Function<String, Object> convert = v -> v.matches("[0-9]+") ? (Object) Integer.valueOf(v) : v;\nMap<String, Object> map = new TreeMap<>();\nfor (String pair : s.substring(1, s.length() - 1).split(",")) {\n    String[] kv = pair.split(":");\n    map.put(kv[0], convert.apply(kv[1]));\n}\nfor (Map.Entry<String, Object> e : map.entrySet()) System.out.println(e.getKey() + "=" + e.getValue() + " (" + e.getValue().getClass().getSimpleName() + ")");', ["{name:asha,age:20,city:pune}", "{x:1}", "{b:two,a:2}", "{id:7,tag:A1}", "{k:v,n:100}"], [("String", "s")], imports="java.util.function.Function")
jq("j-f-reactive-pipeline", "A Publisher-Subscriber Pipeline", "HARD", T, "Simulate a reactive pipeline: `Publisher<T>` keeps subscribers (`Consumer<T>`); `map(f)` and `filter(p)` return new publishers that pass on only transformed or matching items. Read `n` integers and publish them through `filter(x -> x % 2 == 0)` then `map(x -> x * 10)`; the subscriber prints `Got <value>` for each, and a second subscriber on the source counts all items. After the last item print `Source items: <n>`.", "First line `n`, then `n` integers.", "`Got` lines then a count.", "1 <= n <= 100",
   'Publisher<Integer> source = new Publisher<>();\nint[] count = {0};\nsource.subscribe(x -> count[0]++);\nsource.filter(x -> x % 2 == 0).map(x -> x * 10).subscribe(x -> System.out.println("Got " + x));\nfor (int x : a) source.publish(x);\nSystem.out.println("Source items: " + count[0]);', [arr([1, 2, 3, 4]), arr([5]), arr([2, 4, 6]), arr([7, 9]), arr([10, 11, 12])], [("arr", "n a")], imports="java.util.function.*",
   classes='class Publisher<T> {\n    private final List<Consumer<T>> subscribers = new ArrayList<>();\n    void subscribe(Consumer<T> s) {\n        subscribers.add(s);\n    }\n    void publish(T item) {\n        for (Consumer<T> s : subscribers) s.accept(item);\n    }\n    Publisher<T> filter(Predicate<T> keep) {\n        Publisher<T> next = new Publisher<>();\n        subscribe(x -> {\n            if (keep.test(x)) next.publish(x);\n        });\n        return next;\n    }\n    <R> Publisher<R> map(Function<T, R> f) {\n        Publisher<R> next = new Publisher<>();\n        subscribe(x -> next.publish(f.apply(x)));\n        return next;\n    }\n}')
jq("j-f-mini-database", "A Mini Query Engine", "HARD", T, "Build a tiny in-memory table with generics, lambdas and streams: `Table<T>` with `where(Predicate<T>)`, `orderBy(Comparator<T>)`, `limit(int)` and `select(Function<T, R>)`. Read `n` rows `name marks`, then `min` and `k`. Query: rows with marks at least `min`, ordered by marks (highest first, ties by name), the first `k`, selecting `<name>(<marks>)`. Print the selected values one per line (or `No rows`).", "Line 1 `n`; `n` lines `name marks`; then `min k`.", "The result rows.", "1 <= n <= 50",
   'List<Row> rows = new ArrayList<>();\nfor (int i = 0; i < n; i++) rows.add(new Row(in.next(), in.nextInt()));\nint min = in.nextInt(), k = in.nextInt();\nList<String> result = new Table<>(rows).where(r -> r.marks >= min).orderBy((x, y) -> x.marks != y.marks ? y.marks - x.marks : x.name.compareTo(y.name)).limit(k).select(r -> r.name + "(" + r.marks + ")");\nif (result.isEmpty()) System.out.println("No rows");\nfor (String s : result) System.out.println(s);', ["4\nasha 82\nravi 91\nmeena 77\nkiran 91\n80 2", "2\na 10\nb 20\n50 3", "3\nx 60\ny 60\nz 60\n60 5", "1\nsolo 99\n0 1", "3\np 5\nq 6\nr 7\n6 1"], [("int", "n")], imports="java.util.function.* java.util.stream.*",
   classes='class Row {\n    final String name;\n    final int marks;\n    Row(String name, int marks) {\n        this.name = name;\n        this.marks = marks;\n    }\n}\n\nclass Table<T> {\n    private final List<T> rows;\n    Table(List<T> rows) {\n        this.rows = rows;\n    }\n    Table<T> where(Predicate<T> p) {\n        return new Table<>(rows.stream().filter(p).collect(Collectors.toList()));\n    }\n    Table<T> orderBy(Comparator<T> c) {\n        return new Table<>(rows.stream().sorted(c).collect(Collectors.toList()));\n    }\n    Table<T> limit(int k) {\n        return new Table<>(rows.stream().limit(k).collect(Collectors.toList()));\n    }\n    <R> List<R> select(Function<T, R> f) {\n        return rows.stream().map(f).collect(Collectors.toList());\n    }\n}')
